var e={schemaVersion:1,id:`dfeb7314c88ea7fab28ed430`,revision:`8552c54e3dacc7d59333408349d9f50be385821b3a6cd677d4c106e25b3acd5e`,html:`<p class="ngde">The <code class="ngde">thin-scrollbars</code> SCSS mixin adds a 6 px scrollbar with a rounded thumb and track, and hides the scrollbar corner. It also sets <code class="ngde">overflow: auto</code>, so the element scrolls only when its content overflows.</p><h2 id="demo" href="styles/thin-scrollbars" headinglink="true" class="ngde">Demo<ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="demo"></ng-doc-heading-anchor></h2><p class="ngde">The code sample overflows in both directions. Scroll it to see the styled bars.</p><ng-doc-demo componentname="ThinScrollbarsDemo" indexable="false" class="ngde"><div id="options" class="ngde">{}</div></ng-doc-demo><h2 id="usage" href="styles/thin-scrollbars" headinglink="true" class="ngde">Usage<ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="usage"></ng-doc-heading-anchor></h2><p class="ngde">Include the mixin in the stylesheet of the element that should scroll:</p><pre class="shiki shiki-themes css-variables css-variables" style="background-color:var(--ng-doc-code-background);--shiki-dark-bg:var(--ng-doc-code-background);color:var(--ng-doc-syntax-plain);--shiki-dark:var(--ng-doc-syntax-plain)" tabindex="0" highlightedlines="[]"><code class="language-scss"><span class="line"><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">@</span><span style="color:var(--ng-doc-syntax-keyword);--shiki-dark:var(--ng-doc-syntax-keyword)" class="ngde">use</span><span style="color:var(--ng-doc-syntax-string);--shiki-dark:var(--ng-doc-syntax-string)" class="ngde"> "@grumptech/ngx-matx/thin-scrollbars"</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">.</span><span style="color:var(--ng-doc-syntax-function);--shiki-dark:var(--ng-doc-syntax-function)" class="ngde">scrollable</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde"> {</span></span>
<span class="line"><span style="color:var(--ng-doc-syntax-type);--shiki-dark:var(--ng-doc-syntax-type)" class="ngde">  max-height</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">:</span><span style="color:var(--ng-doc-syntax-number);--shiki-dark:var(--ng-doc-syntax-number)" class="ngde"> 20rem</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">;</span></span>
<span class="line"><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">  @</span><span style="color:var(--ng-doc-syntax-keyword);--shiki-dark:var(--ng-doc-syntax-keyword)" class="ngde">include</span><span style="color:var(--ng-doc-syntax-plain);--shiki-dark:var(--ng-doc-syntax-plain)" class="ngde"> thin-scrollbars</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">.</span><span style="color:var(--ng-doc-syntax-function);--shiki-dark:var(--ng-doc-syntax-function)" class="ngde">scrollbars</span><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">;</span></span>
<span class="line"><span style="color:var(--ng-doc-syntax-punctuation);--shiki-dark:var(--ng-doc-syntax-punctuation)" class="ngde">}</span></span></code></pre><h2 id="api" href="styles/thin-scrollbars" headinglink="true" class="ngde">API<ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="api"></ng-doc-heading-anchor></h2><p class="ngde">The <code class="ngde">scrollbars</code> mixin sets <code class="ngde">overflow: auto</code>, a 6 px scrollbar width and height, rounded thumb and track, and hides the scrollbar corner. The custom thumb, track, and corner styles use WebKit scrollbar selectors; other browsers retain their native scrollbar appearance.</p>`};export{e as default};